/**
 * gate-registry.mjs — v2.6 wave-gate VQA (M2, 2026-06-11).
 *
 * Loader for the committed gate-registry snapshot
 * (`boilerplate-gate-registry.json`, generated by
 * `scripts/generate-gate-registry-snapshot.mjs` in the admin repo and
 * drift-guarded by gate-registry-snapshot.test.ts).
 *
 * This replaces the `../sst-env-shared/boilerplate-registry-snapshot.mjs`
 * import in agent-daemon.mjs that pointed at a file NEVER generated — for
 * three weeks every wave gate ran the hardcoded catch-fallback instead of
 * the registry's command. The snapshot is plain JSON living INSIDE daemon/
 * so every rsync ships it; no build step on the EC2 side.
 */
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const SNAPSHOT_PATH = join(
  dirname(fileURLToPath(import.meta.url)),
  'boilerplate-gate-registry.json',
);

let cached;

/**
 * Returns the full snapshot object (keyed by boilerplate type) or null when
 * the file is missing/unreadable — callers MUST keep their legacy fallback.
 */
export function loadGateRegistry({ force = false } = {}) {
  if (cached !== undefined && !force) return cached;
  try {
    cached = JSON.parse(readFileSync(SNAPSHOT_PATH, 'utf8'));
  } catch {
    cached = null;
  }
  return cached;
}

/**
 * Gate entry for one boilerplate type:
 * `{ postMergeValidationCmd, qaContext, qualityGate }` — or null.
 * Mirrors `normalizeBoilerplateType` for legacy `'nextjs'` App rows.
 */
export function getGateEntry(boilerplateType) {
  const reg = loadGateRegistry();
  if (!reg) return null;
  const type = !boilerplateType || boilerplateType === 'nextjs' ? 'nextjs-base' : boilerplateType;
  return reg[type] ?? null;
}
